        <section className="app-card weekly-progress-card"><CardHeading title="تداوم تمرین" subtitle="۸ هفتهٔ اخیر" icon="activity" /><div className="weekly-chart" aria-label="نمودار حضور در ۸ هفتهٔ گذشته">{[58, 74, 68, 90, 72, 83, 77, 95].map((height, index) => <div className="weekly-chart-column" key={index}><span style={{ height: `${height}%` }} className={index === 7 ? 'chart-bar chart-bar-current' : 'chart-bar'} /><small>{['۱۷', '۱۸', '۱۹', '۲۰', '۲۱', '۲۲', '۲۳', '۲۴'][index]}</small></div>)}</div><div className="chart-footer"><span><i />حضور در تمرین</span><b>۹۲٪<small> میانگین فصل</small></b></div></section>

