function SessionDetail({ session, date, confirmed, onConfirm }) {
  return <div className="session-detail"><div className={`session-detail-banner session-${session.color}`}><span><Icon name={session.id === 'wednesday' ? 'dumbbell' : 'activity'} size={24} /></span><div><b>{session.title}</b><small>{WEEKDAYS[session.day]} · {persianDate(date, { day: 'numeric', month: 'long' })}</small></div></div><div className="detail-rows"><div><Icon name="clock" /><span>زمان</span><b>{session.start} تا {session.end}</b></div><div><Icon name="users" /><span>گروه</span><b>{session.group}</b></div><div><Icon name="pin" /><span>محل</span><b>{session.hall}</b></div><div><Icon name="user" /><span>مربی</span><b>{session.coach}</b></div></div><div className="detail-tip"><Icon name="info" size={16} />حداقل ۱۵ دقیقه پیش از شروع، در سالن حاضر باش.</div><Button variant={confirmed ? 'soft' : 'primary'} className="btn-block" onClick={onConfirm}>{confirmed ? <><Check size={16} />حضور تأیید شده</> : 'تأیید حضور نمایشی'}</Button></div>
}

function SchedulePage() {
  const { notify } = useApp()
  const [weekOffset, setWeekOffset] = useState(0)
  const [dayFilter, setDayFilter] = useState('all')
  const [selected, setSelected] = useState(null)
  const [confirmed, setConfirmed] = useState({})
  const weekStart = getWeekStart(weekOffset)
  const sessions = useMemo(() => weekSessions.filter((session) => dayFilter === 'all' || session.day === Number(dayFilter)).sort((a, b) => a.day - b.day || a.start.localeCompare(b.start)), [dayFilter])
  const periodTitle = `${persianDate(weekStart, { day: 'numeric', month: 'long' })} تا ${persianDate(addDays(weekStart, 6), { day: 'numeric', month: 'long', year: 'numeric' })}`
  const handleConfirm = (sessionId) => {
    setConfirmed((current) => ({ ...current, [sessionId]: !current[sessionId] }))
    notify(confirmed[sessionId] ? 'تأیید حضور لغو شد.' : 'حضور نمایشی شما ثبت شد.', confirmed[sessionId] ? 'info' : 'success')
    setSelected(null)
  }
  return <div className="page-enter"><PageHeader eyebrow="برنامهٔ هفتگی" title="برنامهٔ تمرین" description="جلسه‌ها را مرور کن، فیلتر کن و برای حضور برنامه‌ریزی کن." actions={<Button variant="outline" onClick={() => notify(`برنامهٔ ${periodTitle} آمادهٔ چاپ است.`, 'info')}><Icon name="file" size={16} />چاپ برنامه</Button>} />
    <section className="schedule-toolbar app-card"><div className="week-switcher"><button className="icon-button" type="button" onClick={() => setWeekOffset((value) => value - 1)} aria-label="هفتهٔ قبل"><Icon name="chevronRight" /></button><div><b>{weekOffset === 0 ? 'هفتهٔ جاری' : weekOffset < 0 ? `${Math.abs(weekOffset).toLocaleString('fa-IR')} هفتهٔ قبل` : `${weekOffset.toLocaleString('fa-IR')} هفتهٔ بعد`}</b><small>{periodTitle}</small></div><button className="icon-button" type="button" onClick={() => setWeekOffset((value) => Math.min(value + 1, 5))} aria-label="هفتهٔ بعد"><Icon name="chevronLeft" /></button></div><div className="day-filters" role="tablist" aria-label="فیلتر روز"><button type="button" role="tab" aria-selected={dayFilter === 'all'} className={dayFilter === 'all' ? 'filter-chip filter-selected' : 'filter-chip'} onClick={() => setDayFilter('all')}>همهٔ روزها</button>{[0, 1, 2, 3, 4].map((day) => <button key={day} type="button" role="tab" aria-selected={dayFilter === String(day)} className={dayFilter === String(day) ? 'filter-chip filter-selected' : 'filter-chip'} onClick={() => setDayFilter(String(day))}>{WEEKDAYS[day]}</button>)}</div></section>
    <div className="schedule-page-layout"><section className="timeline-list" aria-label="جلسه‌های برنامه‌ریزی‌شده">{sessions.length ? sessions.map((session, index) => { const date = sessionDate(weekOffset, session.day); const past = weekOffset < 0 || (weekOffset === 0 && getDayIndex(new Date()) > session.day); const done = past; return <article className={`timeline-session${done ? ' timeline-session-done' : ''}`} key={session.id} style={{ '--stagger': `${index * 55}ms` }}><div className="timeline-date"><b>{WEEKDAYS[session.day]}</b><small>{persianDate(date, { day: 'numeric', month: 'short' })}</small></div><span className={`timeline-dot timeline-dot-${session.color}`} /><div className="session-card app-card"><div className="session-card-top"><span className={`mini-session-icon session-${session.color}`}><Icon name={session.id === 'wednesday' ? 'dumbbell' : 'activity'} /></span><span className="session-card-title"><b>{session.title}</b><small>{session.group} · {session.coach}</small></span><Pill tone={done ? 'muted' : 'blue'}>{done ? 'برگزار شد' : confirmed[session.id] ? 'حضور تأیید شد' : 'پیش‌رو'}</Pill></div><div className="session-card-meta"><span><Icon name="clock" size={14} />{session.start} – {session.end}</span><span><Icon name="pin" size={14} />{session.hall}</span><span><Icon name="users" size={14} />{session.spots ? `${session.spots.toLocaleString('fa-IR')} ظرفیت باقی‌مانده` : 'مسابقه'}</span></div><div className="session-card-actions"><button className="text-button" type="button" onClick={() => setSelected({ session, date })}>جزئیات جلسه<Icon name="arrowLeft" size={14} /></button>{!done && <button className={`btn btn-sm ${confirmed[session.id] ? 'btn-soft' : 'btn-outline'}`} type="button" onClick={() => handleConfirm(session.id)}>{confirmed[session.id] ? <><Check size={14} />تأیید شد</> : 'تأیید حضور'}</button>}</div></div></article> }) : <EmptyState icon="calendar" title="جلسه‌ای پیدا نشد" text="برای روز انتخاب‌شده برنامه‌ای ثبت نشده است." action={<Button variant="outline" onClick={() => setDayFilter('all')}>نمایش همهٔ روزها</Button>} />}</section>
      <aside className="schedule-aside-column"><section className="app-card schedule-coach-card"><span className="large-avatar coach-avatar-orange">س</span><Pill tone="orange">مربی هفته</Pill><h2>{coach.name}</h2><p>{coach.role} · {coach.experience}</p><blockquote>{coach.note}</blockquote><a href={`tel:${coach.phone.replaceAll(' ', '')}`} className="btn btn-soft btn-block"><Phone size={15} />تماس با مربی</a></section><section className="app-card schedule-guidelines"><CardHeading title="یادآوری جلسه" icon="info" /><ul><li><Check size={14} />۱۵ دقیقه زودتر در سالن حاضر شو.</li><li><Check size={14} />کفش سالنی و بطری آب همراه داشته باش.</li><li><Check size={14} />تغییر سانس را با پشتیبانی هماهنگ کن.</li></ul><Link to="/support" className="card-action-link">سوالی داری؟<Icon name="arrowLeft" size={14} /></Link></section></aside></div>
    <Modal open={Boolean(selected)} onClose={() => setSelected(null)} title="جزئیات جلسه" subtitle="برنامهٔ گروه بازیکن" icon="calendar" size="sm">{selected && <SessionDetail session={selected.session} date={selected.date} confirmed={confirmed[selected.session.id]} onConfirm={() => handleConfirm(selected.session.id)} />}</Modal>
  </div>
}

function getAttendanceState(date) {
  const now = new Date()
  now.setHours(23, 59, 59, 999)
  const weekday = getDayIndex(date)
  if (![0, 2, 4].includes(weekday)) return ''
  if (date > now) return 'upcoming'
  const seed = date.getDate() + date.getMonth() * 3
  return seed % 7 === 2 ? 'absent' : 'present'
}

function AttendancePage() {
  const today = todayAtLoad
  const [monthDate, setMonthDate] = useState(new Date(today.getFullYear(), today.getMonth(), 1))
  const [selectedDate, setSelectedDate] = useState(new Date(today.getFullYear(), today.getMonth(), today.getDate()))
  const monthTitle = new Intl.DateTimeFormat('fa-IR-u-ca-persian', { month: 'long', year: 'numeric' }).format(monthDate)
  const monthDays = new Date(monthDate.getFullYear(), monthDate.getMonth() + 1, 0).getDate()
  const firstOffset = getDayIndex(monthDate)
  const selectedState = getAttendanceState(selectedDate)
  const previousMonth = () => setMonthDate((date) => new Date(date.getFullYear(), date.getMonth() - 1, 1))
  const nextMonth = () => setMonthDate((date) => new Date(date.getFullYear(), date.getMonth() + 1, 1))
  const cells = Array.from({ length: firstOffset }, (_, index) => ({ key: `blank-${index}`, empty: true }))
  for (let day = 1; day <= monthDays; day += 1) cells.push({ key: day, date: new Date(monthDate.getFullYear(), monthDate.getMonth(), day) })
  const selectedDescription = selectedState === 'present' ? 'در این جلسه حضور داشتی. آفرین، همین‌طور ادامه بده!' : selectedState === 'absent' ? 'برای این جلسه غیبت ثبت شده است. اگر موجه بوده با مربی هماهنگ کن.' : selectedState === 'upcoming' ? 'این جلسه هنوز برگزار نشده است؛ برای یادآوری برنامه را بررسی کن.' : 'در این روز جلسه‌ای برای گروهت ثبت نشده است.'
  return <div className="page-enter"><PageHeader eyebrow="عملکرد حضور" title="حضور و غیاب" description="سوابق حضور در تمرین‌ها و جلسات پیش‌رو را در تقویم ببین." actions={<Button variant="outline" onClick={() => window.print()}><Icon name="file" size={16} />چاپ گزارش</Button>} />
    <div className="attendance-summary-grid"><section className="app-card attendance-rate-card"><div className="attendance-ring-wrap"><Ring value={92} label="۹۲٪" detail="نرخ حضور" tone="green" /></div><div className="attendance-rate-copy"><Pill tone="success" icon="trending">منظم و پایدار</Pill><h2>حضور عالیه، ادامه بده!</h2><p>نرخ حضورت از میانگین گروه بالاتر است. هر جلسه یک فرصت تازه برای بهترشدن است.</p><div className="attendance-legend"><span><i className="att-dot att-present" />حاضر <b>۲۲ جلسه</b></span><span><i className="att-dot att-absent" />غایب <b>۲ جلسه</b></span><span><i className="att-dot att-upcoming" />پیش‌رو <b>۳ جلسه</b></span></div></div></section><div className="attendance-stat-column"><StatCard icon="calendarCheck" label="حضور در فصل" value="۲۲ / ۲۴" tone="green" footnote="جلسه‌های برگزارشده" /><StatCard icon="flame" label="استریک فعلی" value="۵ جلسه" tone="orange" footnote="بدون غیبت پیاپی" /><StatCard icon="activity" label="نظم تمرینی" value="۹۰٪" tone="blue" footnote="میانگین گروه: ۸۲٪" /></div></div>
    <div className="attendance-calendar-layout"><section className="app-card attendance-calendar-card"><div className="calendar-top"><div><span className="eyebrow"><span className="eyebrow-line" />تقویم حضور</span><h2>{monthTitle}</h2></div><div className="calendar-navigation"><button type="button" className="icon-button" onClick={previousMonth} aria-label="ماه قبل"><Icon name="chevronRight" /></button><button type="button" className="icon-button" onClick={nextMonth} aria-label="ماه بعد"><Icon name="chevronLeft" /></button></div></div><div className="calendar-grid calendar-weekdays">{WEEKDAYS_SHORT.map((day, index) => <span key={`${day}-${index}`}>{day}</span>)}</div><div className="calendar-grid calendar-days">{cells.map((cell) => cell.empty ? <span className="calendar-empty" key={cell.key} /> : <button type="button" key={cell.key} className={`calendar-day${isSameDate(cell.date, selectedDate) ? ' calendar-day-selected' : ''}${isSameDate(cell.date, today) ? ' calendar-day-today' : ''}`} onClick={() => setSelectedDate(cell.date)} aria-label={persianDate(cell.date, { weekday: 'long', day: 'numeric', month: 'long' })}>{new Intl.NumberFormat('fa-IR').format(cell.date.getDate())}{getAttendanceState(cell.date) && <i className={`calendar-state state-${getAttendanceState(cell.date)}`} />}</button>)}</div><div className="calendar-legend"><span><i className="att-dot att-present" />حاضر</span><span><i className="att-dot att-absent" />غایب</span><span><i className="att-dot att-upcoming" />پیش‌رو</span><span><i className="att-dot att-today" />امروز</span></div></section><section className="app-card selected-day-card"><CardHeading title="جزئیات روز انتخاب‌شده" subtitle={persianDate(selectedDate, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })} icon="calendar" /><div className={`selected-day-status selected-${selectedState || 'empty'}`}><span>{selectedState === 'present' ? <Icon name="checkCircle" size={19} /> : selectedState === 'absent' ? <Icon name="close" size={19} /> : selectedState === 'upcoming' ? <Icon name="clock" size={19} /> : <Icon name="calendar" size={19} />}</span><div><b>{selectedState === 'present' ? 'حضور ثبت شده' : selectedState === 'absent' ? 'غیبت ثبت شده' : selectedState === 'upcoming' ? 'جلسهٔ پیش‌رو' : 'بدون جلسه'}</b><small>{selectedDescription}</small></div></div>{selectedState && <div className="detail-rows attendance-session-rows"><div><Icon name="activity" /><span>نوع جلسه</span><b>تمرین تکنیک و دریافت</b></div><div><Icon name="clock" /><span>زمان</span><b>۱۸:۰۰ تا ۱۹:۳۰</b></div><div><Icon name="pin" /><span>محل</span><b>سالن اصلی</b></div></div>}<Link className="btn btn-soft btn-block" to="/schedule">رفتن به برنامهٔ کامل<Icon name="arrowLeft" size={15} /></Link></section></div>
    <section className="app-card attendance-history"><CardHeading title="روند حضور در هفته‌های اخیر" subtitle="میانگین حضور در ۸ هفتهٔ اخیر" icon="chart" /><div className="attendance-bars">{[76, 88, 66, 100, 78, 90, 84, 92].map((value, index) => <div className="attendance-bar-col" key={index}><b>{value.toLocaleString('fa-IR')}٪</b><span className="attendance-bar-track"><i style={{ height: `${value}%` }} /></span><small>{['هفته ۱', 'هفته ۲', 'هفته ۳', 'هفته ۴', 'هفته ۵', 'هفته ۶', 'هفته ۷', 'این هفته'][index]}</small></div>)}</div></section>
  </div>
}

function TuitionPage() {
  const { payments, setPayments, notify } = useApp()
  const [payTarget, setPayTarget] = useState(null)
  const [receipt, setReceipt] = useState(null)
  const [filter, setFilter] = useState('all')
  const pending = payments.find((item) => item.status === 'pending')
  const paidTotal = payments.filter((item) => item.status === 'paid').reduce((sum, item) => sum + item.amount, 0)
  const visiblePayments = payments.filter((item) => filter === 'all' || item.status === filter)
  const pay = () => {
    if (!payTarget) return
    setPayments((items) => items.map((item) => item.id === payTarget.id ? { ...item, status: 'paid', paidOn: persianDate(new Date()) } : item))
    notify('پرداخت نمایشی ثبت شد؛ هیچ پولی جابه‌جا نشد.', 'success')
    setReceipt({ ...payTarget, status: 'paid', paidOn: persianDate(new Date()) })
    setPayTarget(null)
  }
  const status = (item) => item.status === 'paid' ? <Pill tone="success" icon="check">پرداخت شده</Pill> : item.status === 'pending' ? <Pill tone="warning">در انتظار پرداخت</Pill> : <Pill tone="danger">منقضی شده</Pill>
  return <div className="page-enter"><PageHeader eyebrow="مالی باشگاه" title="شهریه و پرداخت" description="وضعیت شهریه، سررسید بعدی و تاریخچهٔ پرداخت‌ها." actions={<Button variant="outline" onClick={() => notify('گزارش مالی نمونه آمادهٔ چاپ است.', 'info')}><Icon name="download" size={16} />دریافت گزارش</Button>} />
    <div className="tuition-summary-grid"><section className="tuition-current-card"><div className="tuition-current-top"><span className="tuition-icon"><Icon name="wallet" size={20} /></span><Pill tone={pending ? 'warning' : 'success'}>{pending ? 'نیازمند پرداخت' : 'تسویه‌شده'}</Pill></div><small>شهریهٔ دورهٔ جاری</small><h2>{pending ? pending.title : 'وضعیت حساب شما'}</h2><div className="tuition-amount"><b>{money(pending?.amount ?? 0)}</b><span>تومان</span></div><div className="tuition-current-meta"><span><Icon name="calendar" size={15} />سررسید: <b>{pending?.due ?? 'تسویه شده'}</b></span><span><Icon name="lock" size={15} />پرداخت در این نسخه غیرفعال است</span></div><button type="button" className="btn btn-primary btn-block" disabled={!pending} onClick={() => setPayTarget(pending)}>{pending ? 'ادامهٔ پرداخت نمایشی' : 'شهریه تسویه شده'}<Icon name="arrowLeft" size={16} /></button><p className="demo-caption"><Icon name="info" size={13} />فقط وضعیت محلی تغییر می‌کند؛ اتصال بانکی وجود ندارد.</p></section><div className="tuition-stats"><StatCard icon="checkCircle" label="پرداخت‌های انجام‌شده" value={`${payments.filter((item) => item.status === 'paid').length.toLocaleString('fa-IR')} مورد`} tone="green" footnote="از ابتدای عضویت" /><StatCard icon="wallet" label="مجموع پرداخت‌شده" value={`${money(paidTotal)} تومان`} tone="blue" footnote="مجموع رکوردهای نمونه" /><StatCard icon="calendar" label="موعد بعدی" value={pending?.due ?? 'تعیین نشده'} tone="orange" footnote="با پشتیبانی هماهنگ کن" /></div></div>
    <section className="app-card payment-history-card"><div className="history-heading"><CardHeading title="تاریخچهٔ تراکنش‌ها" subtitle={`${payments.length.toLocaleString('fa-IR')} رکورد نمایشی`} icon="file" /><div className="day-filters payment-filters" role="tablist" aria-label="فیلتر تراکنش"><button type="button" className={`filter-chip${filter === 'all' ? ' filter-selected' : ''}`} aria-selected={filter === 'all'} onClick={() => setFilter('all')}>همه</button><button type="button" className={`filter-chip${filter === 'paid' ? ' filter-selected' : ''}`} aria-selected={filter === 'paid'} onClick={() => setFilter('paid')}>پرداخت‌شده</button><button type="button" className={`filter-chip${filter === 'pending' ? ' filter-selected' : ''}`} aria-selected={filter === 'pending'} onClick={() => setFilter('pending')}>در انتظار</button><button type="button" className={`filter-chip${filter === 'expired' ? ' filter-selected' : ''}`} aria-selected={filter === 'expired'} onClick={() => setFilter('expired')}>منقضی‌شده</button></div></div><div className="payment-table"><div className="payment-table-head"><span>عنوان</span><span>سررسید</span><span>مبلغ</span><span>وضعیت</span><span>عملیات</span></div>{visiblePayments.map((item) => <div className="payment-table-row" key={item.id}><span className="payment-name"><i className={`payment-type-icon type-${item.status}`}><Icon name={item.kind.includes('شهریه') ? 'wallet' : item.kind.includes('مسابقه') ? 'trophy' : 'zap'} size={16} /></i><span><b>{item.title}</b><small>{item.kind}</small></span></span><span className="payment-date">{item.due}</span><b className="payment-cell-amount">{money(item.amount)} <small>تومان</small></b><span>{status(item)}</span><span className="payment-action-cell">{item.status === 'paid' ? <button type="button" className="icon-button" aria-label={`مشاهدهٔ رسید ${item.title}`} onClick={() => setReceipt(item)}><Icon name="file" size={16} /></button> : item.status === 'pending' ? <button type="button" className="btn btn-soft btn-sm" onClick={() => setPayTarget(item)}>پرداخت</button> : <Link className="text-button" to="/support">پشتیبانی</Link>}</span></div>)}</div>{visiblePayments.length === 0 && <EmptyState icon="wallet" title="تراکنشی پیدا نشد" text="برای این فیلتر موردی ثبت نشده است." />}</section>
    <Modal open={Boolean(payTarget)} onClose={() => setPayTarget(null)} title="پرداخت نمایشی" subtitle="بدون اتصال به درگاه پرداخت" icon="wallet" size="sm" footer={<><Button variant="ghost" onClick={() => setPayTarget(null)}>انصراف</Button><Button onClick={pay}>ثبت پرداخت نمایشی<Icon name="check" size={15} /></Button></>}>{payTarget && <div className="pay-confirm"><div className="pay-confirm-amount"><small>{payTarget.title}</small><b>{money(payTarget.amount)} <em>تومان</em></b></div><p>با تأیید، وضعیت این مورد فقط در حافظهٔ مرورگر به «پرداخت‌شده» تغییر می‌کند. هیچ تراکنش مالی انجام نمی‌شود.</p></div>}</Modal>
    <Modal open={Boolean(receipt)} onClose={() => setReceipt(null)} title="رسید پرداخت نمایشی" subtitle="این رسید سند مالی واقعی نیست." icon="file" size="sm" footer={<Button variant="outline" onClick={() => { setReceipt(null); notify('رسید نمایشی آمادهٔ چاپ است.', 'info') }}><Icon name="file" size={15} />بستن رسید</Button>}>{receipt && <div className="receipt-card"><div className="receipt-check"><CheckCircle2 size={24} /></div><div className="detail-rows"><div><span>شرح</span><b>{receipt.title}</b></div><div><span>مبلغ</span><b>{money(receipt.amount)} تومان</b></div><div><span>تاریخ پرداخت</span><b>{receipt.paidOn || '۱۲ شهریور ۱۴۰۵'}</b></div><div><span>کد پیگیری</span><bdi>FZ-{receipt.id.toUpperCase()}-1405</bdi></div></div></div>}</Modal>
  </div>
}

function InsurancePage() {
  const { notify } = useApp()
  const [cardOpen, setCardOpen] = useState(false)
  const [claimOpen, setClaimOpen] = useState(false)
  const [claim, setClaim] = useState({ date: '', description: '' })
  const [error, setError] = useState('')
  const coverage = ['آسیب‌دیدگی حین تمرین و مسابقهٔ رسمی', 'هزینه‌های پزشکی طبق سقف تعهد بیمه‌گر', 'مسئولیت مدنی در قبال سایر بازیکنان', 'هماهنگی برای حمل‌ونقل اضطراری در مسابقه']
  const sendClaim = (event) => {
    event.preventDefault()
    if (!claim.date || claim.description.trim().length < 10) { setError('تاریخ و شرح حادثه (حداقل ۱۰ نویسه) را وارد کن.'); return }
    setError(''); setClaimOpen(false); setClaim({ date: '', description: '' }); notify('گزارش حادثهٔ نمایشی ثبت شد؛ برای رسیدگی واقعی با پشتیبانی تماس بگیر.', 'success')
  }
  return <div className="page-enter"><PageHeader eyebrow="پوشش ورزشی" title="بیمهٔ ورزشی" description="اطلاعات بیمه و راه‌های پیگیری را در یک نگاه ببین." actions={<Pill tone="success" icon="check">بیمهٔ فعال</Pill>} />
    <div className="insurance-layout"><section className="insurance-main"><div className="insurance-card"><div className="insurance-card-glow" /><div className="insurance-card-top"><span className="insurance-brand"><span className="insurance-brand-mark">F</span><span><b>FARAZ</b><small>باشگاه والیبال فراز</small></span></span><Pill tone="translucent" icon="shield">فعال</Pill></div><div className="insurance-member-label">بیمه‌شده</div><h2>احمد احمدی</h2><div className="insurance-card-grid"><span>شمارهٔ بیمه‌نامه<bdi>۰۵۱۴-۸۸۲۰-۲۳</bdi></span><span>بیمه‌گر<b>بیمهٔ ورزشی اعضا</b></span><span>تاریخ اعتبار<b>۱ مهر ۱۴۰۵ تا ۳۱ شهریور ۱۴۰۶</b></span><span>سقف تعهد<b>طبق شرایط بیمه‌نامه</b></span></div><div className="insurance-card-bottom"><span className="barcode" aria-hidden="true">▍▌▏▌▍▎▌▏▍▌▍▏▎▌▍▏▌▍▎▏▌▍▌</span><span>کارت دیجیتال عضو</span></div></div><div className="insurance-action-row"><Button variant="outline" onClick={() => setCardOpen(true)}><Icon name="file" size={16} />مشاهدهٔ جزئیات بیمه‌نامه</Button><Button variant="soft" onClick={() => setClaimOpen(true)}><Icon name="send" size={16} />ثبت گزارش حادثه</Button></div></section>
      <div className="insurance-side"><section className="app-card coverage-card"><CardHeading title="پوشش‌های بیمه" subtitle="مرور کلی موارد قابل پیگیری" icon="shield" /><ul className="coverage-list">{coverage.map((item) => <li key={item}><span><Check size={14} /></span>{item}</li>)}</ul><p className="insurance-disclaimer">توجه: پوشش قطعی، سقف تعهد و شرایط استفاده فقط بر اساس بیمه‌نامهٔ رسمی معتبر است.</p></section><section className="insurance-help-card"><span><Phone size={18} /></span><div><b>نیاز به پیگیری داری؟</b><p>برای دریافت نسخهٔ رسمی یا اعلام حادثه با پشتیبانی هماهنگ کن.</p><a href="tel:02188776655">تماس با باشگاه<Icon name="arrowLeft" size={14} /></a></div></section></div></div>
    <div className="insurance-info-grid"><StatCard icon="calendar" label="شروع پوشش" value="۱ مهر ۱۴۰۵" tone="blue" footnote="عضویت این فصل" /><StatCard icon="clock" label="اعتبار تا" value="۳۱ شهریور ۱۴۰۶" tone="orange" footnote="پیش از انقضا تمدید کن" /><StatCard icon="support" label="وضعیت پرونده" value="بدون پروندهٔ باز" tone="green" footnote="گزارش‌های ثبت‌شده اینجا نمایش داده می‌شوند" /></div>
    <Modal open={cardOpen} onClose={() => setCardOpen(false)} title="جزئیات بیمه‌نامه" subtitle="اطلاعات نمونه؛ نسخهٔ رسمی را از باشگاه بگیر." icon="shield" size="sm" footer={<Button onClick={() => setCardOpen(false)}>متوجه شدم</Button>}><div className="detail-rows"><div><span>بیمه‌شده</span><b>احمد احمدی</b></div><div><span>شمارهٔ بیمه‌نامه</span><bdi>۰۵۱۴-۸۸۲۰-۲۳</bdi></div><div><span>اعتبار</span><b>۱ مهر ۱۴۰۵ تا ۳۱ شهریور ۱۴۰۶</b></div><div><span>نوع پوشش</span><b>فعالیت ورزشی در چارچوب بیمه‌نامه</b></div></div></Modal>
    <Modal open={claimOpen} onClose={() => setClaimOpen(false)} title="ثبت گزارش حادثه" subtitle="فرم نمایشی؛ گزارش به جایی ارسال نمی‌شود." icon="send" size="sm"><form className="modal-form" onSubmit={sendClaim} noValidate><label className="form-field"><span>تاریخ حادثه</span><input type="date" value={claim.date} onChange={(event) => setClaim({ ...claim, date: event.target.value })} /></label><label className="form-field"><span>شرح حادثه</span><textarea rows="4" placeholder="شرح کوتاه و دقیق بنویس…" value={claim.description} onChange={(event) => setClaim({ ...claim, description: event.target.value })} /></label>{error && <p className="form-alert" role="alert">{error}</p>}<div className="modal-form-actions"><Button variant="ghost" type="button" onClick={() => setClaimOpen(false)}>انصراف</Button><Button type="submit"><Send size={15} />ثبت گزارش نمایشی</Button></div></form></Modal>
  </div>
}

function ProgressPage() {
  const [activeTab, setActiveTab] = useState('skills')
  const weeks = [
    { label: 'هفته ۱', value: 66 }, { label: 'هفته ۲', value: 78 }, { label: 'هفته ۳', value: 70 }, { label: 'هفته ۴', value: 86 },
    { label: 'هفته ۵', value: 73 }, { label: 'هفته ۶', value: 92 }, { label: 'هفته ۷', value: 84 }, { label: 'این هفته', value: 96 }
  ]
  return <div className="page-enter"><PageHeader eyebrow="عملکرد شما" title="پیشرفت من" description="نظم تمرینی، رشد مهارت‌ها و دستاوردهایت را دنبال کن." actions={<Pill tone="blue" icon="calendar">آخرین ارزیابی · مهر ۱۴۰۵</Pill>} />
    <section className="progress-hero"><div className="progress-hero-copy"><span className="eyebrow eyebrow-light"><span className="eyebrow-line" />جمع‌بندی عملکرد</span><h2>مسیرت رو به <em>پیشرفت</em> است.</h2><p>در این ماه در دریافت و دفاع پیشرفت خوبی داشتی. با استمرار تمرین، به هدف بعدی نزدیک می‌شوی.</p><div className="progress-hero-meta"><span><TrendingUp size={15} />رشد کلی این ماه <b>۶٪+</b></span><span><Icon name="trophy" size={15} />۲ نشان کسب‌شده</span></div></div><div className="progress-hero-score"><Ring value={82} label="۸۲" detail="امتیاز کلی" size="large" tone="white" /><small>نسبت به ماه قبل <b>۶٪+ رشد</b></small></div></section>
    <div className="progress-stats-grid"><StatCard icon="activity" label="میانگین مهارت" value="۷۷٪" change="۶٪ رشد ماهانه" tone="orange" /><StatCard icon="calendarCheck" label="نرخ حضور" value="۹۲٪" change="۴٪ رشد" tone="green" /><StatCard icon="flame" label="استریک تمرین" value="۵ جلسه" change="بهترین: ۸ جلسه" tone="blue" /><StatCard icon="trophy" label="نشان‌ها" value="۲ از ۴" change="۲ نشان تا سطح بعد" tone="violet" /></div>
    <div className="progress-tabs" role="tablist" aria-label="جزئیات پیشرفت"><button type="button" role="tab" aria-selected={activeTab === 'skills'} className={activeTab === 'skills' ? 'progress-tab active' : 'progress-tab'} onClick={() => setActiveTab('skills')}>مهارت‌ها</button><button type="button" role="tab" aria-selected={activeTab === 'consistency'} className={activeTab === 'consistency' ? 'progress-tab active' : 'progress-tab'} onClick={() => setActiveTab('consistency')}>تداوم تمرین</button><button type="button" role="tab" aria-selected={activeTab === 'achievements'} className={activeTab === 'achievements' ? 'progress-tab active' : 'progress-tab'} onClick={() => setActiveTab('achievements')}>دستاوردها</button></div>
    {activeTab === 'skills' && <div className="progress-content-grid"><section className="app-card skills-detail-card"><CardHeading title="ارزیابی مهارت‌های والیبال" subtitle="مقیاس صفر تا صد · ارزیابی مربی" icon="chart" /><div className="skills-detail-list">{skillStats.map((skill, index) => <div className="skills-detail-row" key={skill.name}><span className={`skill-number skill-tone-${skill.color}`}>{new Intl.NumberFormat('fa-IR', { minimumIntegerDigits: 2 }).format(index + 1)}</span><span className="skill-name">{skill.name}</span><ProgressBar value={skill.value} tone={skill.color} /><b>{skill.value.toLocaleString('fa-IR')}٪</b><small className="skill-trend"><TrendingUp size={13} />+{[5, 4, 8, 3, 6, 2][index].toLocaleString('fa-IR')}٪</small></div>)}</div><div className="coach-feedback"><span className="coach-note-avatar">س</span><p><b>یادداشت {coach.name}:</b> «دفاع و دریافتت بهتر شده؛ برای سرویس پرشی روی ثبات پرتاب توپ تمرکز کن.»</p></div></section><section className="app-card skill-focus-card"><CardHeading title="تمرکز بعدی" subtitle="هدف تمرینی پیشنهادی" icon="target" /><div className="focus-target"><span><Icon name="zap" size={23} /></span><small>هدف این ماه</small><h3>سرویس پرشی با دقت</h3><p>۸ از ۱۰ سرویس را در منطقهٔ هدف بنشان.</p><ProgressBar value={64} tone="orange" label="پیشرفت هدف" showValue /><div className="focus-deadline"><Icon name="calendar" size={14} />بازبینی بعدی · پایان ماه</div></div><Link className="btn btn-soft btn-block" to="/schedule">دیدن برنامهٔ تمرین<Icon name="arrowLeft" size={15} /></Link></section></div>}
    {activeTab === 'consistency' && <section className="app-card consistency-detail-card"><CardHeading title="نظم تمرینی در هشت هفته" subtitle="حضور در جلسات برنامه‌ریزی‌شده" icon="calendarCheck" /><div className="consistency-chart">{weeks.map((week) => <div className="consistency-col" key={week.label}><span className="consistency-value">{week.value.toLocaleString('fa-IR')}٪</span><div className="consistency-track"><i style={{ height: `${week.value}%` }} /></div><small>{week.label}</small></div>)}</div><div className="consistency-summary"><span><i className="att-dot att-present" />میانگین حضور</span><b>۸۱٪</b><span>هدف پیشنهادی</span><b>۹۰٪</b></div></section>}
    {activeTab === 'achievements' && <section className="app-card achievements-detail-card"><CardHeading title="دستاوردهای بازیکن" subtitle="نشان‌هایی که با استمرار تمرین می‌گیری" icon="trophy" /><div className="achievement-grid-full">{achievementList.map((item) => <article key={item.title} className={`achievement-full${item.unlocked ? '' : ' achievement-full-locked'}`}><span className="achievement-full-icon"><Icon name={item.icon} size={21} /></span><div><b>{item.title}</b><p>{item.subtitle}</p></div><Pill tone={item.unlocked ? 'success' : 'muted'}>{item.unlocked ? 'کسب‌شده' : 'قفل'}</Pill></article>)}</div></section>}
  </div>
}

function AnnouncementsPage() {
  const { announcements, setAnnouncements } = useApp()
  const [category, setCategory] = useState('همه')
  const [search, setSearch] = useState('')
  const categories = ['همه', ...Array.from(new Set(announcements.map((item) => item.category)))]
  const visible = announcements.filter((item) => (category === 'همه' || item.category === category) && (!search || `${item.title} ${item.text}`.toLowerCase().includes(search.toLowerCase())))
  const markRead = (id) => setAnnouncements((items) => items.map((item) => item.id === id ? { ...item, read: true } : item))
  return <div className="page-enter"><PageHeader eyebrow="اخبار باشگاه" title="اعلانات" description="اطلاعیه‌ها و خبرهای رسمی باشگاه را دنبال کن." actions={<Pill tone="orange" icon="zap">{announcements.filter((item) => item.important).length.toLocaleString('fa-IR')} اطلاعیهٔ مهم</Pill>} />
    <section className="announcement-toolbar app-card"><div className="day-filters" role="tablist" aria-label="دسته‌بندی اطلاعیه‌ها">{categories.map((item) => <button type="button" role="tab" aria-selected={category === item} className={`filter-chip${category === item ? ' filter-selected' : ''}`} key={item} onClick={() => setCategory(item)}>{item}</button>)}</div><label className="announcement-search"><Icon name="search" size={16} /><input type="search" placeholder="جستجو در اعلانات…" value={search} onChange={(event) => setSearch(event.target.value)} /></label></section>
    <div className="announcement-list">{visible.map((item) => <article key={item.id} className={`announcement-card app-card${item.important ? ' announcement-important' : ''}${item.read ? ' announcement-read' : ''}`}><span className={`announcement-type-icon announcement-${item.category === 'پرداخت' ? 'payment' : item.category === 'مسابقه' ? 'match' : item.important ? 'important' : 'general'}`}><Icon name={item.category === 'پرداخت' ? 'wallet' : item.category === 'مسابقه' ? 'trophy' : item.category === 'تمرین' ? 'activity' : 'zap'} size={18} /></span><div className="announcement-copy"><div className="announcement-title-line"><h2>{item.title}</h2>{item.important && <Pill tone="warning">مهم</Pill>}{!item.read && <span className="unread-label"><i />جدید</span>}</div><p>{item.text}</p><div className="announcement-meta"><Pill tone="muted">{item.category}</Pill><span><Icon name="clock" size={13} />{item.date}</span></div></div><button className="announcement-read-button" type="button" onClick={() => markRead(item.id)} aria-label={item.read ? 'خوانده شده' : 'علامت‌گذاری به‌عنوان خوانده‌شده'}>{item.read ? <Icon name="checkCircle" size={18} /> : <span className="unread-ring" />}</button></article>)}{visible.length === 0 && <EmptyState icon="search" title="نتیجه‌ای پیدا نشد" text="فیلتر یا عبارت جستجو را تغییر بده." action={<Button variant="outline" onClick={() => { setSearch(''); setCategory('همه') }}>پاک کردن فیلترها</Button>} />}</div>
    <div className="local-data-note"><Icon name="info" size={15} />اطلاعیه‌ها نمونه‌اند و با سرویس یا سرور همگام‌سازی نمی‌شوند.</div>
  </div>
}

function ProfilePage() {
  const { profile, updateProfile, notify } = useApp()
  const [editOpen, setEditOpen] = useState(false)
  const [draft, setDraft] = useState(profile)
  const [error, setError] = useState('')
  const openEdit = () => { setDraft(profile); setError(''); setEditOpen(true) }
  const save = (event) => {
    event.preventDefault()
    if (!draft.firstName.trim() || !draft.lastName.trim() || !/^\+?[0-9\s-]{8,16}$/.test(draft.phone.trim()) || !/^\S+@\S+\.\S+$/.test(draft.email.trim())) { setError('نام، شمارهٔ تماس و ایمیل معتبر را کامل کن.'); return }
    updateProfile(draft); setEditOpen(false); notify('اطلاعات پروفایل در مرورگر ذخیره شد.', 'success')
  }
  const personal = [['نام', profile.firstName], ['نام خانوادگی', profile.lastName], ['تاریخ تولد', profile.birth], ['شمارهٔ تماس', profile.phone], ['ایمیل', profile.email], ['شهر', profile.city]]
  const sport = [['سطح', profile.level], ['گروه', profile.group], ['مربی', coach.name], ['پست', profile.position], ['شمارهٔ پیراهن', profile.number], ['سال عضویت', profile.joined]]
  return <div className="page-enter"><PageHeader eyebrow="حساب بازیکن" title="پروفایل من" description="اطلاعات شخصی و ورزشی خود را مرور و ویرایش کن." actions={<Button onClick={openEdit}><Icon name="settings" size={16} />ویرایش اطلاعات</Button>} />
    <section className="profile-banner"><span className="profile-banner-number">{profile.number}</span><div className="profile-avatar-large">{profile.firstName.slice(0, 1)}</div><div className="profile-banner-copy"><span className="profile-member-id">عضو از {profile.joined} · شناسه {profile.playerId}</span><h2>{profile.firstName} {profile.lastName}</h2><div className="profile-tags"><Pill tone="orange">{profile.role}</Pill><Pill tone="translucent">سطح {profile.level}</Pill><Pill tone="translucent">گروه {profile.group}</Pill></div></div><div className="profile-banner-stat"><b>۹۲٪</b><small>نرخ حضور</small></div></section>
    <div className="profile-content-grid"><section className="app-card"><CardHeading title="اطلاعات شخصی" subtitle="اطلاعات تماس و حساب" icon="user" action={<button type="button" className="text-button" onClick={openEdit}>ویرایش<Icon name="arrowLeft" size={14} /></button>} /><div className="profile-info-list">{personal.map(([label, value]) => <div className="profile-info-row" key={label}><span>{label}</span><b className={['شمارهٔ تماس', 'ایمیل'].includes(label) ? 'profile-ltr' : ''}>{value}</b></div>)}</div></section><section className="app-card"><CardHeading title="اطلاعات ورزشی" subtitle="عضویت و گروه تمرینی" icon="activity" /><div className="profile-info-list">{sport.map(([label, value]) => <div className="profile-info-row" key={label}><span>{label}</span><b>{value}</b></div>)}</div></section></div>
    <div className="profile-footer-cards"><Link to="/insurance" className="profile-link-card"><span className="profile-link-icon"><Icon name="shield" /></span><span><b>بیمهٔ ورزشی</b><small>وضعیت پوشش و اعتبار</small></span><Icon name="arrowLeft" size={17} /></Link><Link to="/progress" className="profile-link-card"><span className="profile-link-icon link-blue"><Icon name="chart" /></span><span><b>گزارش پیشرفت</b><small>ارزیابی و مهارت‌ها</small></span><Icon name="arrowLeft" size={17} /></Link></div>
    <Modal open={editOpen} onClose={() => setEditOpen(false)} title="ویرایش پروفایل" subtitle="تغییرات فقط در همین مرورگر ذخیره می‌شود." icon="user" size="md"><form className="modal-form profile-edit-form" onSubmit={save} noValidate><div className="profile-form-grid">{[['firstName', 'نام', 'احمد'], ['lastName', 'نام خانوادگی', 'احمدی'], ['phone', 'شمارهٔ تماس', '0912 345 6789'], ['email', 'ایمیل', 'name@example.com'], ['birth', 'تاریخ تولد', '۱۳۸۸/۰۴/۱۲'], ['city', 'شهر', 'تهران']].map(([key, label, placeholder]) => <label className="form-field" key={key}><span>{label}</span><input type={key === 'email' ? 'email' : 'text'} value={draft[key] ?? ''} placeholder={placeholder} dir={['phone', 'email'].includes(key) ? 'ltr' : undefined} onChange={(event) => setDraft({ ...draft, [key]: event.target.value })} /></label>)}</div>{error && <p className="form-alert" role="alert">{error}</p>}<div className="modal-form-actions"><Button variant="ghost" type="button" onClick={() => setEditOpen(false)}>انصراف</Button><Button type="submit"><Icon name="check" size={15} />ذخیرهٔ تغییرات</Button></div></form></Modal>
  </div>
}

function SettingsPage() {
  const { theme, setTheme, preferences, updatePreference, notify, profile, updateProfile } = useApp()
  const [passwordOpen, setPasswordOpen] = useState(false)
  const [passwordForm, setPasswordForm] = useState({ current: '', next: '', repeat: '' })
  const [passwordError, setPasswordError] = useState('')
  const [resetOpen, setResetOpen] = useState(false)
  const switches = [
    ['trainingReminder', 'یادآور تمرین', 'یک روز قبل از هر جلسهٔ تمرینی'],
    ['paymentReminder', 'یادآوری شهریه', 'پیش از موعد پرداخت دوره'],
    ['newsReminder', 'اعلان‌های باشگاه', 'خبرها و اطلاعیه‌های تازه'],
    ['emailCopy', 'رونوشت ایمیلی', 'دریافت نسخهٔ ایمیلی اعلان‌ها']
  ]
  const savePassword = (event) => {
    event.preventDefault()
    if (!passwordForm.current || passwordForm.next.length < 8 || passwordForm.next !== passwordForm.repeat) { setPasswordError('رمز فعلی را وارد کن؛ رمز جدید باید حداقل ۸ نویسه و با تکرار یکسان باشد.'); return }
    setPasswordError(''); setPasswordOpen(false); setPasswordForm({ current: '', next: '', repeat: '' }); notify('تغییر رمز در نسخهٔ نمایشی ثبت شد؛ رمز واقعی تغییر نکرد.', 'info')
  }
  const resetLocal = () => {
    updateProfile(playerSeed)
    Object.keys(preferences).forEach((key) => updatePreference(key, ['trainingReminder', 'paymentReminder', 'newsReminder'].includes(key)))
    setResetOpen(false)
    notify('پروفایل نمایشی به مقادیر اولیه برگشت.', 'success')
  }
  return <div className="page-enter"><PageHeader eyebrow="ترجیحات" title="تنظیمات" description="ظاهر پنل، اعلان‌ها و گزینه‌های حساب را مدیریت کن." />
    <div className="settings-grid"><div className="settings-left-column"><section className="app-card settings-card"><CardHeading title="حساب کاربری" subtitle="اطلاعات پایهٔ ورود" icon="user" /><div className="settings-account-row"><span className="avatar avatar-md">{profile.firstName.slice(0, 1)}</span><div><b>{profile.firstName} {profile.lastName}</b><small>{profile.email}</small></div><Link className="btn btn-outline btn-sm" to="/profile">پروفایل<Icon name="arrowLeft" size={14} /></Link></div><div className="settings-row"><div><b>شمارهٔ تماس</b><small dir="ltr">{profile.phone}</small></div><a href="tel:02188776655" className="text-button">درخواست تغییر</a></div><div className="settings-row"><div><b>زبان رابط کاربری</b><small>زبان و چینش صفحه</small></div><span className="language-chip">فارسی <span>RTL</span></span></div></section>
        <section className="app-card settings-card"><CardHeading title="اعلان‌ها" subtitle="انتخاب کن چه چیزی به تو یادآوری شود" icon="bell" />{switches.map(([key, label, hint]) => <div className="settings-row" key={key}><div><b>{label}</b><small>{hint}</small></div><button type="button" role="switch" aria-checked={Boolean(preferences[key])} className={`switch${preferences[key] ? ' switch-on' : ''}`} onClick={() => { updatePreference(key, !preferences[key]); notify('ترجیحات اعلان ذخیره شد.', 'success') }}><span /></button></div>)}</section></div>
      <div className="settings-right-column"><section className="app-card settings-card"><CardHeading title="ظاهر پنل" subtitle="پوستهٔ دلخواهت را انتخاب کن" icon="sun" /><div className="theme-choice-grid"><button type="button" className={`theme-choice theme-choice-dark${theme === 'dark' ? ' theme-choice-active' : ''}`} aria-pressed={theme === 'dark'} onClick={() => setTheme('dark')}><span className="theme-preview theme-preview-dark"><i /><i /><i /></span><b>تیره</b><small>پیش‌فرض</small></button><button type="button" className={`theme-choice theme-choice-light${theme === 'light' ? ' theme-choice-active' : ''}`} aria-pressed={theme === 'light'} onClick={() => setTheme('light')}><span className="theme-preview theme-preview-light"><i /><i /><i /></span><b>روشن</b><small>محیط روشن</small></button></div></section>
        <section className="app-card settings-card"><CardHeading title="امنیت" subtitle="گزینه‌های محافظت حساب" icon="shield" /><div className="settings-row"><div><b>رمز عبور</b><small>آخرین تغییر: —</small></div><Button variant="soft" size="sm" onClick={() => setPasswordOpen(true)}><Icon name="shield" size={14} />تغییر رمز</Button></div><div className="settings-row"><div><b>ورود دومرحله‌ای</b><small>نسخهٔ نمایشی؛ بدون پیامک واقعی</small></div><button type="button" role="switch" aria-checked={Boolean(preferences.twoFactor)} className={`switch${preferences.twoFactor ? ' switch-on' : ''}`} onClick={() => { updatePreference('twoFactor', !preferences.twoFactor); notify('تنظیم امنیتی نمایشی ذخیره شد.', 'info') }}><span /></button></div></section>
        <section className="settings-danger-zone"><div><span><Icon name="info" size={17} /></span><b>ذخیره‌سازی محلی</b></div><p>تنظیمات و برخی تغییرها فقط در حافظهٔ مرورگر ذخیره می‌شوند و روی سامانهٔ باشگاه اثری ندارند.</p><button type="button" className="text-button danger-text" onClick={() => setResetOpen(true)}>بازنشانی پروفایل نمایشی<Icon name="arrowLeft" size={14} /></button></section></div></div>
    <Modal open={passwordOpen} onClose={() => setPasswordOpen(false)} title="تغییر رمز نمایشی" subtitle="این تغییر واقعی نیست و به سرور ارسال نمی‌شود." icon="shield" size="sm"><form className="modal-form" onSubmit={savePassword} noValidate>{[['current', 'رمز فعلی'], ['next', 'رمز جدید'], ['repeat', 'تکرار رمز جدید']].map(([key, label]) => <label className="form-field" key={key}><span>{label}</span><input type="password" value={passwordForm[key]} onChange={(event) => setPasswordForm({ ...passwordForm, [key]: event.target.value })} autoComplete="new-password" /></label>)}{passwordError && <p className="form-alert" role="alert">{passwordError}</p>}<div className="modal-form-actions"><Button variant="ghost" type="button" onClick={() => setPasswordOpen(false)}>انصراف</Button><Button type="submit">ثبت نمایشی</Button></div></form></Modal>
    <Modal open={resetOpen} onClose={() => setResetOpen(false)} title="بازنشانی دادهٔ نمایشی" subtitle="فقط اطلاعات محلی پروفایل تغییر می‌کند." icon="info" size="sm" footer={<><Button variant="ghost" onClick={() => setResetOpen(false)}>انصراف</Button><Button variant="danger" onClick={resetLocal}>بازنشانی</Button></>}><p className="modal-copy">پروفایل به اطلاعات نمونهٔ اولیه برمی‌گردد. اطلاعات واقعی یا دادهٔ سرور وجود ندارد.</p></Modal>
  </div>
}

function SupportPage() {
  const { notify } = useApp()
  const [ticketOpen, setTicketOpen] = useState(false)
  const [ticket, setTicket] = useState({ category: 'اداری و ثبت‌نام', message: '' })
  const [tickets, setTickets] = useState([])
  const [error, setError] = useState('')
  const faqsSupport = faqs.slice(0, 4)
  const sendTicket = (event) => {
    event.preventDefault()
    if (ticket.message.trim().length < 10) { setError('شرح درخواست باید دست‌کم ۱۰ نویسه باشد.'); return }
    const code = `FZ-${Math.floor(100000 + Math.random() * 899999).toLocaleString('fa-IR')}`
    setTickets((items) => [{ ...ticket, code, date: persianDate(new Date()) }, ...items])
    setTicket({ category: 'اداری و ثبت‌نام', message: '' }); setError(''); setTicketOpen(false); notify(`درخواست نمایشی با کد ${code} ثبت شد.`, 'success')
  }
  return <div className="page-enter"><PageHeader eyebrow="کمک و ارتباط" title="پشتیبانی" description="راه‌های تماس، پاسخ پرسش‌ها و ثبت درخواست نمایشی." actions={<Button onClick={() => setTicketOpen(true)}><Icon name="send" size={16} />ثبت درخواست</Button>} />
    <div className="support-layout"><div className="support-left"><section className="app-card support-contact-card"><CardHeading title="تماس با باشگاه" subtitle="شنبه تا چهارشنبه، ۱۶ تا ۲۱" icon="support" /><a className="support-contact-row" href="tel:02188776655"><span className="support-contact-icon support-orange"><Icon name="phone" /></span><span><b>تلفن دفتر</b><small>پاسخگویی در ساعات کاری</small></span><strong><bdi>۰۲۱-۸۸۷۷۶۶۵۵</bdi></strong><Icon name="arrowLeft" size={15} /></a><a className="support-contact-row" href="mailto:club@vc.ir"><span className="support-contact-icon support-blue"><Icon name="mail" /></span><span><b>ایمیل باشگاه</b><small>پاسخ تا یک روز کاری</small></span><strong><bdi>club@vc.ir</bdi></strong><Icon name="arrowLeft" size={15} /></a><div className="support-contact-row support-address"><span className="support-contact-icon support-green"><Icon name="pin" /></span><span><b>نشانی سالن</b><small>تهران، بلوار ورزش، مجموعهٔ فراز</small></span></div></section><section className="support-ticket-callout"><div><span><Icon name="message" size={18} /></span><b>درخواستی داری؟</b><p>فرم کوتاه را پر کن تا کد پیگیری نمایشی دریافت کنی.</p></div><Button variant="white" onClick={() => setTicketOpen(true)}>ارسال درخواست<Icon name="arrowLeft" size={15} /></Button></section></div><section className="app-card support-faq-card"><CardHeading title="سؤالات متداول" subtitle="پاسخ‌های کوتاه و کاربردی" icon="help" /><div className="support-faq-list">{faqsSupport.map((item, index) => <details key={item.q} className="support-faq-item" open={index === 0}><summary>{item.q}<Icon name="chevronDown" size={16} /></summary><p>{item.a}</p></details>)}</div><Link className="support-faq-link" to="/#faq">دیدن همهٔ پرسش‌ها<Icon name="arrowLeft" size={14} /></Link></section></div>
    {tickets.length > 0 && <section className="app-card support-ticket-list"><CardHeading title="درخواست‌های ثبت‌شده" subtitle="فقط در این نشست مرورگر" icon="file" />{tickets.map((item) => <div className="ticket-row" key={item.code}><span><b>{item.category}</b><small>{item.date} · کد پیگیری {item.code}</small></span><Pill tone="warning">در انتظار پاسخ</Pill></div>)}</section>}
    <div className="local-data-note"><Icon name="info" size={15} />درخواست‌ها به پشتیبانی ارسال نمی‌شوند؛ این بخش صرفاً برای نمایش فرانت‌اند است.</div>
    <Modal open={ticketOpen} onClose={() => setTicketOpen(false)} title="ثبت درخواست پشتیبانی" subtitle="فرم نمایشی؛ اطلاعات به سرور ارسال نمی‌شود." icon="send" size="sm"><form className="modal-form" onSubmit={sendTicket} noValidate><label className="form-field"><span>موضوع درخواست</span><select value={ticket.category} onChange={(event) => setTicket({ ...ticket, category: event.target.value })}><option>اداری و ثبت‌نام</option><option>شهریه و امور مالی</option><option>تمرین و برنامه</option><option>بیمه و پزشکی</option><option>سایر موارد</option></select></label><label className="form-field"><span>شرح درخواست</span><textarea rows="5" placeholder="موضوع را کوتاه و روشن توضیح بده…" value={ticket.message} onChange={(event) => setTicket({ ...ticket, message: event.target.value })} /></label>{error && <p className="form-alert" role="alert">{error}</p>}<div className="modal-form-actions"><Button variant="ghost" type="button" onClick={() => setTicketOpen(false)}>انصراف</Button><Button type="submit"><Icon name="send" size={15} />ثبت درخواست</Button></div></form></Modal>
  </div>
}

function NotFoundPage() {
  return <div className="not-found-page"><div className="not-found-mark">۴۰۴</div><h1>این صفحه پیدا نشد</h1><p>شاید آدرس اشتباه است یا صفحه جابه‌جا شده.</p><Link className="btn btn-primary" to="/">بازگشت به خانه<Icon name="arrowLeft" size={16} /></Link></div>
}

export {
  DashboardPage, SchedulePage, AttendancePage, TuitionPage, InsurancePage,
  ProgressPage, AnnouncementsPage, ProfilePage, SettingsPage, SupportPage, NotFoundPage
}
